import { isNil, isObject, isPlainObject, isString, isUndefined, } from '@nestjs/common/internal';
/**
 * @publicApi
 */
export class KafkaRequestSerializer {
    serialize(value) {
        const isNotKafkaMessage = isNil(value) ||
            !isObject(value) ||
            (!('key' in value) && !('value' in value));
        // Serialize a copy, headers included: ClientKafka and ServerKafka write
        // correlation metadata into the returned headers, and the caller's record
        // may be frozen, reused or sent concurrently.
        const record = (isNotKafkaMessage ? { value } : value);
        const request = { ...record, headers: { ...record.headers } };
        request.value = this.encode(request.value);
        if (!isNil(request.key)) {
            request.key = this.encode(request.key);
        }
        return request;
    }
    encode(value) {
        const isObjectOrArray = !isNil(value) && !isString(value) && !Buffer.isBuffer(value);
        if (isObjectOrArray) {
            return isPlainObject(value) ||
                Array.isArray(value) ||
                value.toString == Object.prototype.toString // Prevent default [object Object] behavior
                ? JSON.stringify(value)
                : value.toString();
        }
        else if (isUndefined(value)) {
            return null;
        }
        return value;
    }
}
